    {{
      "issue_id": "iss-01",
      "stage": "system_architecture",
      "field_path": "control_domains[0].id",
      "severity": "error|warning|info",
      "code": "MISSING_FIELD|INVALID_REFERENCE|EMPTY_VALUE|TYPE_MISMATCH|BROKEN_CROSS_REF|MISSING_CHECKPOINT|PREREQ_GAP|OLD_DOMAIN_LANGUAGE",
      "message": "Precise description of the issue",
      "suggested_fix": "What needs to be corrected"
    }}
  ],
  "stage_summaries": [
    {{
      "stage": "system_architecture",
      "status": "pass|fail|warn",
      "issue_count": 0
    }}
  ],
  "render_ready": true,
  "export_ready": true,
  "audit_summary": "One paragraph describing whether the tutorial is structurally complete and ready to render/export"
}}
